policy:
{
  // A subnet route or exit node lets a device carry traffic for addresses that
  // aren't tailnet devices. Two things must be true: the route is APPROVED (an
  // admin approves it, or autoApprovers does), AND a grant opens the destination.
  "tagOwners": {
    "tag:router": ["alice@example.com"],
  },
  "autoApprovers": {
    "routes": {
      "10.1.0.0/16": ["tag:router"],
    },
    "exitNode": ["tag:router"],
  },
  "grants": [
    { "src": ["alice@example.com"], "dst": ["10.1.0.0/16"], "ip": ["*"] },
    { "src": ["alice@example.com"], "dst": ["autogroup:internet"], "ip": ["*"] },
  ],
}
